/* HEXA BATTLEGROUNDS upgrade3 — PART 16 OF 22. For databases that already ran supabase/upgrade-2 (open world); Run in order. Safe to re-run. */ create or replace function _auto_step_name(p_pos int, p_n int) returns text language sql immutable as $$ select case when p_pos <= 0 then 'Finale entry round' when p_pos = 1 then 'Exchange round' when p_pos <= 1 + p_n then 'Finale battle ' || p_pos when p_pos = 2 + p_n then 'Squad 00 reveal' when p_pos = 3 + p_n then 'Final code' when p_pos = 4 + p_n then 'Results locked' when p_pos = 5 + p_n then 'Winner reveal' when p_pos = 6 + p_n then 'Grand champion' else 'Match complete' end $$; create or replace function _auto_status(p_arena uuid) returns jsonb language plpgsql stable as $$ declare a arenas; v_label text; v_at timestamptz; v_n int; v_pos int; v_fm int; r sync_rounds; begin select * into a from arenas where id = p_arena; if a.id is null or not a.autopilot then return jsonb_build_object('on', false); end if; v_n := greatest(1, coalesce(_cfg(a.event_id, 'finale_battles'), 2)); v_fm := _auto_finale_minute(a.event_id); case when a.phase = 'lobby' then v_label := 'Waiting for a ready squad'; when a.phase = 'boarding' then v_label := 'Bus leaves'; v_at := a.auto_next_at; when a.phase = 'shuttle' then v_label := 'Bus arrives'; v_at := a.shuttle_arrive_at; when a.phase = 'roles' then v_label := 'Roles lock'; v_at := a.roles_deadline; when a.phase = 'play' then if a.match_phase < 4 and a.phase_next_at is not null then v_label := 'Phase ' || (a.match_phase + 1); v_at := a.phase_next_at; else v_label := 'Finale'; v_at := a.play_started_at + make_interval(mins => v_fm); end if; when a.phase in ('finale', 'results') then if a.sync_round_id is not null then select * into r from sync_rounds where id = a.sync_round_id; v_label := 'Round ends'; v_at := r.deadline; else v_pos := _auto_fin_pos(a.id); v_label := _auto_step_name(v_pos, v_n); if v_pos < 7 + v_n then v_at := a.auto_next_at; end if; end if; else v_label := 'Match complete'; end case; return jsonb_build_object('on', true, 'step', a.auto_step, 'label', v_label, 'at', v_at, 'length', a.auto_length, 'paused', a.paused); end $$; create or replace function _auto_resync(p_arena uuid) returns void language plpgsql as $$ declare a arenas; begin select * into a from arenas where id = p_arena; update arenas set auto_step = case when a.phase in ('lobby', 'boarding') then 'boarding' when a.phase in ('shuttle', 'roles') then 'ride' when a.phase = 'play' then 'play' when a.phase in ('finale', 'results') then 'fin:' || _auto_fin_pos(a.id) else 'done' end, auto_next_at = case when a.phase = 'boarding' then coalesce(a.auto_next_at, now() + _secs(coalesce(_cfg(a.event_id, 'boarding_seconds'), 18))) when a.phase in ('finale', 'results') then now() + interval '10 seconds' else null end where id = p_arena; end $$;
